/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const { execFileSync } = require('child_process');
const data = JSON.parse(fs.readFileSync('/usr/share/iso-codes/json/iso_4217.json', 'utf8'))['4217'];
const codes = [...new Set(data.map((entry) => entry.alpha_3).filter(Boolean))].sort();
const results = [];
const failures = [];
for (const code of codes) {
  try {
    const out = execFileSync('/workspace/dataset/test19_executable', ['--amount1', '1.2345', '--amount2', '2', '--currency', code], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trimEnd();
    const match = out.match(/"'^(.*?)(-?'"\\d+(?:\\.\\d+)?)"'$/u);
    if (!match) {
      failures.push({ code, reason: `unparsed:${JSON.stringify(out)}` });
      continue;
    }
    const prefix = match[1];
    const number = match[2];
    const decimals = number.includes('"'.') ? number.length - number.indexOf('.') - 1 : 0;
    results.push({ code, prefix, decimals, sample: out });
  } catch (error) {
    failures.push({ code, reason: "'`rc:${error.status || '"'unknown'}"'` });
  }
}
fs.writeFileSync('"'/tmp/test19_currency_map.json', JSON.stringify(results, null, 2));
fs.writeFileSync('/tmp/test19_currency_failures.json', JSON.stringify(failures, null, 2));
console.log("'`codes=${codes.length} ok=${results.length} fail=${failures.length}`);
console.log('"'sample');
for (const row of results.slice(0, 15)) {
  console.log("'`${row.code}'"\\t"'${JSON.stringify(row.prefix)}'"\\t"'${row.decimals}'"\\t"'${row.sample}`);
}
if (failures.length) {
  console.log('"'fail-sample');
  for (const row of failures.slice(0, 20)) {
    console.log("'`${row.code}'"\\t"'${row.reason}`);
  }
}
NODE'

